{
  "correction_rules": [
    "Reduce forecast overshoots following sharp price spikes, especially when sentiment is negative or neutral.",
    "Adjust forecasts downward if sentiment history shows persistent negative sentiment (e.g., -0.20 or -0.25) over recent days.",
    "Apply mean reversion bias: if forecast is significantly above recent 5-day average, reduce by 5-10% for next period.",
    "Increase downward bias when sentiment shifts from positive to negative (e.g., 0.00 → -0.20 or -0.25).",
    "Avoid overreacting to short-term volatility: if true outcome deviates >10% from forecast, apply smoothing filter (e.g., 3-day moving average) before next forecast.",
    "For horizon >15 days, reduce forecast volatility if sentiment remains flat or negative; use sentiment as a decay-weighted filter for long-term bias correction."
  ]
}

{
  "correction_rules": [
    "Reduce forecast bias when sentiment is negative (sentiment < 0) — model tends to overestimate prices.",
    "Adjust downward for forecasts that overshoot recent highs — especially after sentiment spikes.",
    "Apply mean reversion correction for persistent over- or under-forecasting — model exhibits inertia.",
    "Lower forecast for early days of new sentiment trends — model reacts too late to sentiment shifts.",
    "Increase forecast sensitivity to sentiment when sentiment is positive and price is trending down — model underreacts.",
    "Avoid over-optimism in forecasts when sentiment is neutral — model tends to overestimate in flat periods."
  ]
}

{
  "correction_rules": [
    "Reduce forecast overshoots following strong upward sentiment spikes (sentiment > 0.20) by 10-15% to avoid overreaction.",
    "Adjust downward forecasts when sentiment is negative (sentiment < 0.00) by adding a 5-10% bias correction to reflect bearish momentum.",
    "Apply mean reversion bias: if forecast deviates > 10% from recent 5-day average, adjust toward the average by 5-7% per day.",
    "For long-term (30-day) forecasts, reduce volatility by smoothing out extreme outliers (±20% from median) using a 3-point moving average filter.",
    "When sentiment is neutral (0.00), prioritize historical trend alignment over model extrapolation; use 10-day moving average as anchor for correction."
  ]
}

{
  "correction_rules": [
    "Reduce forecast overshoots following strong upward sentiment spikes (e.g., sentiment > 0.20) by 10-15% to avoid overreaction.",
    "Adjust downward forecasts when sentiment is negative (e.g., sentiment < -0.20) by adding a 5-10% buffer to avoid underestimating downside risk.",
    "Apply mean reversion bias correction: if forecast deviates > 10% from recent 5-day average, adjust toward historical mean.",
    "For long-term (30-day) forecasts, reduce volatility in the tail (last 3-5 days) if sentiment is neutral or negative to prevent over-optimism.",
    "When sentiment is positive but recent prices are trending down, slightly dampen forecast growth to avoid lagging the market’s correction.",
    "If forecast consistently overestimates true outcome in early days of a new trend (e.g., first 5 days), apply a 5-10% downward correction to align with sentiment-driven momentum decay."
  ]
}

{
  "correction_rules": [
    "Reduce forecast bias when sentiment is negative (sentiment < 0) — model tends to overestimate prices.",
    "Adjust downward for long-term (30-day) forecasts when recent prices show strong mean reversion or downward momentum.",
    "Apply a lag correction: if true outcome is significantly lower than forecast, reduce next period’s forecast by 5–10% to account for delayed price adjustment.",
    "Cap forecast spikes above 75% of historical max in 15-day window to prevent overshoot after sentiment spikes.",
    "When sentiment is positive (sentiment > 0), slightly increase forecast baseline by 2–5% to reflect bullish momentum.",
    "For forecasts with high volatility (e.g., >15% deviation from true outcome), apply smoothing: average with prior 3-day forecast to reduce noise."
  ]
}
